<?php
declare(strict_types=1);
namespace App\Application\Catalog\Service;
use App\Application\Catalog\Port\PdfTextExtractorInterface;use App\Application\Catalog\Port\TransactionManagerInterface;use App\Domain\Catalog\Entity\SyllabusDocumentExtraction;use App\Domain\Catalog\Entity\SyllabusProcessingJob;use App\Domain\Catalog\Repository\SyllabusDocumentExtractionRepositoryInterface;use App\Domain\Catalog\Repository\SyllabusProcessingJobRepositoryInterface;use App\Domain\Catalog\Repository\SyllabusRepositoryInterface;
final class ProcessSyllabusJobService { public function __construct(private readonly SyllabusProcessingJobRepositoryInterface $jobs,private readonly SyllabusRepositoryInterface $syllabi,private readonly SyllabusDocumentExtractionRepositoryInterface $extractions,private readonly PdfTextExtractorInterface $extractor,private readonly TransactionManagerInterface $transactions){} public function processNext():bool{$job=$this->jobs->claimNext();if($job===null)return false;try{$syllabus=$this->syllabi->findById($job->syllabusId);if($syllabus===null||$syllabus->documentPath===null||$syllabus->documentSha256!==$job->documentSha256)throw new \RuntimeException('PDF do edital indisponivel.');$offset=0;$items=[];foreach($this->extractor->extractPages($syllabus->documentPath) as $index=>$text){$end=$offset+mb_strlen($text);$items[]=new SyllabusDocumentExtraction($this->uuid(),$syllabus->id,$job->documentSha256,$index+1,$text,$offset,$end);$offset=$end+1;}$this->transactions->transactional(fn()=>$this->extractions->replaceForDocument($job->documentSha256,$items));$this->jobs->save(new SyllabusProcessingJob($job->id,$job->syllabusId,$job->documentSha256,'COMPLETED',100,null,$job->createdAt,$job->startedAt,new \DateTimeImmutable('now')));}catch(\Throwable){$this->jobs->save(new SyllabusProcessingJob($job->id,$job->syllabusId,$job->documentSha256,'FAILED',$job->progress,'Nao foi possivel processar o documento.',$job->createdAt,$job->startedAt,new \DateTimeImmutable('now')));}return true;} private function uuid():string{$b=random_bytes(16);$b[6]=chr((ord($b[6])&15)|64);$b[8]=chr((ord($b[8])&63)|128);return vsprintf('%s%s-%s-%s-%s-%s%s%s',str_split(bin2hex($b),4));} }
